insert into public.experiences(id,city_id,title,published,is_seed,content) values('south-bank-walk','london','A walk along the South Bank',true,true,'{"id":"south-bank-walk","cityId":"london","title":"A walk along the South Bank","category":"Outdoors","duration":"1–2 hours","cost":"Free to explore","completedCount":0,"image":"/london-seed.svg","imageAlt":"Original STAMPED illustration of Big Ben and the Thames","description":"A seed experience for testing your London chapter: walk along the Thames and make time for a riverside pause.","tips":[]}'::jsonb) on conflict do nothing;
insert into public.experiences(id,city_id,title,published,is_seed,content) values('akihabara-electric-town','tokyo','Akihabara Electric Town',true,true,'{"id":"akihabara-electric-town","cityId":"tokyo","title":"Akihabara Electric Town","category":"Gaming","duration":"2–4 hours","cost":"Free to explore","completedCount":1248,"image":"/akihabara.jpg","imageAlt":"Neon signs and people crossing the street in Akihabara, Tokyo","description":"Get a little lost in Tokyo’s electric playground. Browse retro games, climb floors of arcades, and follow the neon into the side streets. This is a neighbourhood made for curiosity.","tips":[{"author":"Maya","text":"Start with the side streets. The tiny retro game shops were my favourite part."},{"author":"Jamie","text":"Bring coins for the arcades, and leave some room in your bag."}]}'::jsonb) on conflict do nothing;
insert into public.experiences(id,city_id,title,published,is_seed,content) values('tsukiji-food-walk','tokyo','A taste of Tsukiji',true,true,'{"id":"tsukiji-food-walk","cityId":"tokyo","title":"A taste of Tsukiji","category":"Food","duration":"1–2 hours","cost":"Around ¥2,000–4,000","completedCount":846,"image":"/tsukiji.jpg","imageAlt":"Food stalls and signs at Tsukiji Outer Market","description":"Follow your appetite through the market lanes, stopping for small bites and something you have never tried before.","tips":[{"author":"Alex","text":"Go early and enjoy a few small bites instead of one big meal."}]}'::jsonb) on conflict do nothing;
insert into public.experiences(id,city_id,title,published,is_seed,content) values('harajuku-backstreets','tokyo','Harajuku, off the main street',true,true,'{"id":"harajuku-backstreets","cityId":"tokyo","title":"Harajuku, off the main street","category":"Fashion","duration":"2–3 hours","cost":"Free to explore","completedCount":672,"image":"/harajuku.jpg","imageAlt":"Shops and pedestrians on a Harajuku street in Tokyo","description":"Find independent boutiques, vintage treasures, and street style around the quieter corners of Harajuku.","tips":[{"author":"Sam","text":"Take the small streets off the main drag. Give yourself time to browse."}]}'::jsonb) on conflict do nothing;
insert into public.experiences(id,city_id,title,published,is_seed,content) values('shinjuku-after-dark','tokyo','Shinjuku after dark',true,true,'{"id":"shinjuku-after-dark","cityId":"tokyo","title":"Shinjuku after dark","category":"Nightlife","duration":"2–3 hours","cost":"Around ¥2,000–5,000","completedCount":932,"image":"/akihabara.jpg","imageAlt":"Tokyo neon street scene used as an atmospheric illustration","description":"An evening walk through neon-lit streets, with time to stop for a bite and watch the city come alive.","tips":[{"author":"Rin","text":"Check cover charges before sitting down in a small bar."}]}'::jsonb) on conflict do nothing;
